using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36.R104;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            s.OpenPage("clip");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.ShowUtility();
            w.minSize = w.maxSize = new Vector2(1024, 597.2f);
            w.position = new Rect(0, 0, 1024, 597.2f);
            w.Focus();
            var log = new StringBuilder("Synthetic GameView mouse; API opens initial clip. Clip is silent illustrative animation, not controller footage. Six buttons use same mechanism law.\n");
            int step = 0, index = 0;
            double next = EditorApplication.timeSinceStartup + 3;
            string[] ids = {"release", "help", "hold", "hook", "wedge", "after"};
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200f / 1.25f, y * Screen.height / 800f / 1.25f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .8;
                try
                {
                    if (step == 0)
                    {
                        click(265, 684);
                        step++;
                        next += .4;
                        return;
                    }

                    if (step == 1)
                    {
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/clip-closed-ui.png");
                        log.AppendLine("clip play time=" + s.ClipTime + " latch=" + s.clipGate.state.latched);
                        step++;
                        next += 3;
                        return;
                    }

                    if (step == 2)
                    {
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/clip-release-ui.png");
                        log.AppendLine("clip event time=" + s.ClipTime + " latch=" + s.clipGate.state.latched + " angle=" + s.clipGate.state.angle);
                        step++;
                        next += .5;
                        return;
                    }

                    if (step == 3)
                    {
                        click(100, 684);
                        step++;
                        return;
                    }

                    if (step == 4)
                    {
                        s.OpenPage("reconstruction");
                        step++;
                        return;
                    }

                    if (step == 5)
                    {
                        click(350, 621);
                        click(120, 148 + index * 69);
                        step++;
                        next += 2.6;
                        return;
                    }

                    if (step == 6)
                    {
                        if (s.TrialId != ids[index])
                            throw new Exception("Wrong UI case " + s.TrialId);
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/case-" + ids[index] + "-wide.png");
                        log.AppendLine("UI " + ids[index] + " at=" + s.TrialTime + " state=" + JsonUtility.ToJson(s.modelGate.state));
                        click(550, 621);
                        step++;
                        next += .4;
                        return;
                    }

                    if (step == 7)
                    {
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r104/case-" + ids[index] + "-close.png");
                        if (index == 3)
                        {
                            click(780, 621);
                            next += 1;
                        }

                        step++;
                        next += 6.6;
                        return;
                    }

                    if (step == 8)
                    {
                        log.AppendLine("ENDCASE " + ids[index] + " time=" + s.TrialTime + " state=" + JsonUtility.ToJson(s.modelGate.state));
                        index++;
                        if (index < 6)
                        {
                            step = 5;
                            return;
                        }

                        EditorApplication.update -= f;
                        File.WriteAllText("Test/KetQua/investigation_r104/presentation-ui.txt", log.ToString());
                        return;
                    }
                }
                catch (Exception e)
                {
                    EditorApplication.update -= f;
                    File.WriteAllText("Test/KetQua/investigation_r104/presentation-ui.txt", log + "FAIL " + e);
                }
            };
            EditorApplication.update += f;
            r.Log("Bounded clip + six cases via actual UI buttons");
        }
    }
}

